html:
{%- set card = get_customer_card(doc.name) -%}
{%- macro section(title, count=None) -%}<div class="tc-h"><span>{{ _(title) }}</span>{% if count %}<em>{{ count }}</em>{% endif %}</div>{%- endmacro -%}
{%- macro crore(v) -%}{% if v %}₹ {{ frappe.utils.fmt_money(v, precision=2) }} Cr{% else %}—{% endif %}{%- endmacro -%}
{%- set primary = (card.contacts | selectattr("is_primary") | list | first) or (card.contacts | first) -%}
{%- set status_color = {"Active Customer": "green", "Prospect": "orange", "Inactive": "grey"}.get(doc.customer_status, "grey") -%}
<style>
	.tc { font-family: "Helvetica Neue", Arial, sans-serif; font-size: 10.5px; color: #222; }
	.tc table { width: 100%; border-collapse: collapse; }
	.tc .top td { vertical-align: middle; padding: 0; }
	.tc .top img { height: 46px; }
	.tc .top .doc-title { text-align: right; }
	.tc .top .doc-title b { display: block; font-size: 15px; letter-spacing: 2px; color: #8e2229; }
	.tc .top .doc-title span { color: #777; font-size: 9.5px; }
	.tc .band { height: 4px; background: #8e2229; margin: 8px 0 12px; }
	.tc .name { font-size: 20px; font-weight: 700; margin: 0; color: #111; }
	.tc .sub { color: #666; margin: 3px 0 12px; }
	.tc .pill { display: inline-block; padding: 1px 8px; border-radius: 9px; font-size: 9.5px; font-weight: 600; }
	.tc .pill.green { background: #e3f4ea; color: #1e7b45; }
	.tc .pill.orange { background: #fdf0dc; color: #a35d00; }
	.tc .pill.grey { background: #eee; color: #555; }
	.tc .pill.blue { background: #e4eefb; color: #1f5fae; }
	.tc .pill.red { background: #fbe6e6; color: #a32020; }
	.tc .kpi td { width: 20%; border: 1px solid #e3d4d5; background: #fbf6f6; padding: 7px 9px; }
	.tc .kpi .v { font-size: 13.5px; font-weight: 700; color: #8e2229; }
	.tc .kpi .l { font-size: 9px; color: #777; text-transform: uppercase; letter-spacing: .5px; margin-top: 2px; }
	.tc .info { margin-top: 12px; }
	.tc .info > tbody > tr > td { width: 50%; vertical-align: top; }
	.tc .box { border: 1px solid #e5e5e5; border-radius: 4px; padding: 8px 10px; }
	.tc .box h5 { margin: 0 0 6px; font-size: 10px; color: #8e2229; text-transform: uppercase; letter-spacing: .6px; }
	.tc .kv td { padding: 2px 0; vertical-align: top; }
	.tc .kv td.k { color: #777; width: 34%; }
	.tc .tc-h { margin: 16px 0 6px; padding: 4px 8px; background: #8e2229; color: #fff; font-weight: 700; font-size: 11px; letter-spacing: .4px; }
	.tc .tc-h em { float: right; font-style: normal; font-weight: 400; opacity: .85; }
	.tc .grid th { background: #f4ecec; color: #5a1a1f; font-weight: 600; text-align: left; padding: 4px 6px; border-bottom: 1px solid #d9c3c5; font-size: 9.5px; }
	.tc .grid td { padding: 4px 6px; border-bottom: 1px solid #eee; vertical-align: top; }
	.tc .grid tr:nth-child(even) td { background: #fcfafa; }
	.tc .grid tr { page-break-inside: avoid; }
	.tc .num { text-align: right; white-space: nowrap; }
	.tc .muted { color: #888; font-size: 9.5px; }
	.tc .note { margin: 6px 0 0; padding: 6px 9px; background: #fbf6f6; border-left: 3px solid #8e2229; }
	.tc .foot { margin-top: 18px; padding-top: 6px; border-top: 1px solid #ddd; color: #999; font-size: 9px; }
</style>
<div class="tc">
	<table class="top"><tr>
		<td><img src="/assets/techpark/images/techpark_logo.png" alt="TechPark"></td>
		<td class="doc-title"><b>{{ _("CUSTOMER CARD") }}</b><span>{{ doc.name }} · {{ frappe.utils.formatdate(frappe.utils.nowdate()) }}</span></td>
	</tr></table>
	<div class="band"></div>

	<p class="name">{{ doc.customer_name }}</p>
	<div class="sub">
		<span class="pill {{ status_color }}">{{ _(doc.customer_status) }}</span>
		{% if doc.industry_domain %} &nbsp;{{ doc.industry_domain }}{% endif %}
		{% if doc.territory_region %} &nbsp;·&nbsp; {{ doc.territory_region }}{% endif %}
		{% if doc.group_name %} &nbsp;·&nbsp; {{ _("Group") }}: {{ doc.group_name }}{% endif %}
	</div>

	<table class="kpi"><tr>
		<td><div class="v">{{ crore(doc.annual_turnover_cr) }}</div><div class="l">{{ _("Annual Turnover") }}</div></td>
		<td><div class="v">{{ crore(doc.group_turnover_cr) }}</div><div class="l">{{ _("Group Turnover") }}</div></td>
		<td><div class="v">{{ crore(doc.abrasive_consumption_cr) }}</div><div class="l">{{ _("Abrasive / Year") }}</div></td>
		<td><div class="v">{{ doc.established_year or "—" }}</div><div class="l">{{ _("Established") }}</div></td>
		<td><div class="v">{{ (doc.technical_leads or []) | length }}</div><div class="l">{{ _("Technical Leads") }}</div></td>
	</tr></table>

	<table class="info"><tr>
		<td style="padding-right:6px">
			<div class="box">
				<h5>{{ _("Company") }}</h5>
				<table class="kv">
					<tr><td class="k">{{ _("Address") }}</td><td>{{ (doc.customer_address or "") | replace("\n", ", ") }}{% if doc.plant_location %}{% if doc.customer_address %}, {% endif %}{{ doc.plant_location }}{% endif %}{% if doc.state %}, {{ doc.state }}{% endif %}{% if doc.pincode %} {{ doc.pincode }}{% endif %}</td></tr>
					{% if doc.gstin %}<tr><td class="k">{{ _("GSTIN") }}</td><td>{{ doc.gstin }}</td></tr>{% endif %}
					{% if card.principals %}<tr><td class="k">{{ _("Principals") }}</td><td>{{ card.principals | join(", ") }}</td></tr>{% endif %}
					{% if card.agents %}<tr><td class="k">{{ _("Handled By") }}</td><td>{{ card.agents | join(", ") }}</td></tr>{% endif %}
					{% if doc.total_employees %}<tr><td class="k">{{ _("Employees") }}</td><td>{{ doc.total_employees }}</td></tr>{% endif %}
				</table>
			</div>
		</td>
		<td style="padding-left:6px">
			<div class="box">
				<h5>{{ _("Primary Contact") }}</h5>
				{% if primary %}
				<table class="kv">
					<tr><td class="k">{{ _("Name") }}</td><td><b>{{ primary.person_name }}</b>{% if primary.designation %} <span class="muted">· {{ primary.designation }}</span>{% endif %}</td></tr>
					{% if primary.phone %}<tr><td class="k">{{ _("Phone") }}</td><td>{{ primary.phone }}</td></tr>{% endif %}
					{% if primary.email %}<tr><td class="k">{{ _("Email") }}</td><td>{{ primary.email }}</td></tr>{% endif %}
				</table>
				{% else %}<span class="muted">{{ _("Not recorded") }}</span>{% endif %}
			</div>
		</td>
	</tr></table>

	{% if card.contacts | length > 1 %}
	{{ section("Contacts", card.contacts | length) }}
	<table class="grid">
		<tr><th>{{ _("Name") }}</th><th>{{ _("Designation") }}</th><th>{{ _("Department") }}</th><th>{{ _("Phone") }}</th><th>{{ _("Email") }}</th></tr>
		{% for c in card.contacts %}
		<tr><td>{{ c.person_name }}{% if c.is_primary %} ★{% endif %}</td><td>{{ c.designation or "" }}</td><td>{{ c.department or "" }}</td><td>{{ c.phone or "" }}</td><td>{{ c.email or "" }}</td></tr>
		{% endfor %}
	</table>
	{% endif %}

	{% if card.production %}
	{{ section("Products Range & Production Volume", card.production | length) }}
	<table class="grid">
		<tr><th>{{ _("Product") }}</th><th>{{ _("Category") }}</th><th class="num">{{ _("Production Volume") }}</th></tr>
		{% for r in card.production %}
		<tr><td><b>{{ r.product }}</b></td><td>{{ r.category }}</td><td class="num">{% if r.volume %}{{ frappe.format(r.volume, {"fieldtype": "Float"}) }} {{ r.unit }}{% if r.frequency %} / {{ _(r.frequency) }}{% endif %}{% else %}—{% endif %}</td></tr>
		{% endfor %}
	</table>
	{% if doc.abrasive_consumption_details %}<div class="note"><b>{{ _("Abrasive Consumption") }}:</b> {{ doc.abrasive_consumption_details }}</div>{% endif %}
	{% endif %}

	{% if doc.manufacturing_profile or doc.heat_treatment %}
	{{ section("Company Profile") }}
	<table class="kv">
		{% if doc.manufacturing_profile %}<tr><td class="k" style="width:18%">{{ _("Manufacturing") }}</td><td>{{ doc.manufacturing_profile }}</td></tr>{% endif %}
		{% if doc.heat_treatment %}<tr><td class="k" style="width:18%">{{ _("Heat Treatment") }}</td><td>{{ doc.heat_treatment }}</td></tr>{% endif %}
	</table>
	{% endif %}

	{% if card.machines %}
	{{ section("Machine Details", card.machines | length) }}
	<table class="grid">
		<tr><th>{{ _("Machine / Process") }}</th><th>{{ _("Maker(s)") }}</th><th class="num">{{ _("Qty") }}</th></tr>
		{% for m in card.machines %}
		<tr><td>{{ m.machine_type }}</td><td>{{ m.maker or "" }}</td><td class="num">{{ m.quantity or "" }}</td></tr>
		{% endfor %}
	</table>
	{% endif %}

	{% if card.wheel_specs %}
	{{ section("Current Wheel Usage", card.wheel_specs | length) }}
	<table class="grid">
		<tr><th>{{ _("Application") }}</th><th>{{ _("Wheel Spec") }}</th><th>{{ _("Size") }}</th><th>{{ _("Speed") }}</th><th>{{ _("Pitch Range") }}</th><th class="num">{{ _("Per Year") }}</th></tr>
		{% for r in card.wheel_specs %}
		<tr><td>{{ r.application_title }}</td><td><b>{{ r.wheel_specification or "" }}</b></td><td>{{ r.wheel_size or "" }}</td><td>{{ r.wheel_speed or "" }}</td><td>{{ r.pitch_range or "" }}</td><td class="num">{% if r.annual_consumption %}{{ frappe.format(r.annual_consumption, {"fieldtype": "Float"}) }} {{ r.consumption_unit_title }}{% endif %}</td></tr>
		{% endfor %}
	</table>
	{% endif %}

	{% if doc.technical_leads %}
	{{ section("Technical Leads", doc.technical_leads | length) }}
	<table class="grid">
		<tr><th>{{ _("Application") }}</th><th>{{ _("Process") }}</th><th>{{ _("Category") }}</th><th class="num">{{ _("Annual Demand") }}</th><th>{{ _("Share") }}</th><th>{{ _("M/C") }}</th><th>{{ _("Progress") }}</th></tr>
		{% for r in doc.technical_leads %}
		{%- set shares = [] -%}
		{%- for f, l in [("share_noritake","N"),("share_tyrolit","Tyrolit"),("share_asahi","Asahi"),("share_tvmk","TVMK"),("share_gno","GNO"),("share_cumi","Cumi"),("share_other","Other")] -%}{%- if r.get(f) -%}{%- set added = shares.append(l ~ " " ~ (r.get(f) | round(0) | int) ~ "%") -%}{%- endif -%}{%- endfor -%}
		{%- set pcolor = {"Approved": "green", "Evaluation Failed": "red", "Not Started": "grey"}.get(r.progress, "blue") -%}
		<tr>
			<td><b>{{ r.application or "" }}</b>{% if r.issue or r.action_plan %}<div class="muted">{{ r.issue or "" }}{% if r.action_plan %} → {{ r.action_plan }}{% endif %}</div>{% endif %}</td>
			<td>{{ r.grinding_process or "" }}</td>
			<td>{% if r.supplier_product_category %}{{ frappe.db.get_value("Supplier Product Category", r.supplier_product_category, "category_name") or "" }}{% endif %}</td>
			<td class="num">{% if r.annual_demand_amount %}{{ frappe.utils.fmt_money(r.annual_demand_amount, precision=0, currency="INR") }}{% endif %}</td>
			<td>{{ shares | join(", ") }}</td>
			<td>{{ r.machine_maker or "" }}{% if r.machine_quantity %} × {{ r.machine_quantity }}{% endif %}</td>
			<td>{% if r.progress %}<span class="pill {{ pcolor }}">{{ _(r.progress) }}</span>{% endif %}</td>
		</tr>
		{% endfor %}
	</table>
	{% endif %}

	{% if card.turnovers %}
	{{ section("Turnover History") }}
	<table class="grid">
		<tr><th>{{ _("Financial Year") }}</th><th class="num">{{ _("Amount") }}</th><th>{{ _("Remarks") }}</th></tr>
		{% for r in card.turnovers %}
		<tr><td>{{ r.financial_year }}</td><td class="num">{{ frappe.format(r.amount, {"fieldtype": "Float"}) }} {{ r.unit }}</td><td>{{ r.remarks or "" }}</td></tr>
		{% endfor %}
	</table>
	{% endif %}

	<div class="foot">TechPark International · {{ _("Customer Card") }} · {{ doc.customer_name }}</div>
</div>
